CREATE TABLE analyses (id SERIAL PRIMARY KEY, video_path TEXT NOT NULL, output_path TEXT, status VARCHAR(30) NOT NULL DEFAULT 'queued', progress DOUBLE PRECISION NOT NULL DEFAULT 0, error TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE students (id SERIAL PRIMARY KEY, analysis_id INTEGER NOT NULL REFERENCES analyses(id) ON DELETE CASCADE, track_id INTEGER NOT NULL, seat_id VARCHAR(50), current_risk DOUBLE PRECISION NOT NULL DEFAULT 0, risk_level VARCHAR(20) NOT NULL DEFAULT 'low', last_seen TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE behavior_events (id SERIAL PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, behavior_type VARCHAR(80) NOT NULL, confidence DOUBLE PRECISION NOT NULL, video_timestamp DOUBLE PRECISION NOT NULL, duration DOUBLE PRECISION NOT NULL DEFAULT 0, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE risk_scores (id SERIAL PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, score DOUBLE PRECISION NOT NULL, risk_level VARCHAR(20) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE alerts (id SERIAL PRIMARY KEY, student_id INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE, risk_score DOUBLE PRECISION NOT NULL, reason TEXT NOT NULL, video_timestamp DOUBLE PRECISION NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'open', created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE evidence (id SERIAL PRIMARY KEY, alert_id INTEGER NOT NULL REFERENCES alerts(id) ON DELETE CASCADE, frame_path TEXT NOT NULL, clip_path TEXT, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP);

